<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Compare Interview Experiences</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f8fd;color:#102445;font-family:Inter,system-ui,sans-serif}.wrap{width:min(1150px,calc(100% - 32px));margin:45px auto}.panel{background:#fff;border:1px solid #d6e3f2;border-radius:17px;padding:25px}.selects{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.selects select,.selects button{height:48px;border:1px solid #c4d3e6;border-radius:9px;padding:0 10px}.selects button{background:#286df0;color:#fff;font-weight:800}.table-wrap{overflow:auto;margin-top:24px}table{width:100%;min-width:750px;border-collapse:collapse;background:#fff}th,td{padding:18px;text-align:left;border:1px solid #dce6f2;vertical-align:top}th{background:#eaf2ff}.chips{display:flex;gap:5px;flex-wrap:wrap}.chips span{padding:5px 8px;border-radius:15px;background:#edf5ff;color:#1758b6;font-size:12px}@media(max-width:800px){.selects{grid-template-columns:1fr}}</style></head><body><main class="wrap"><h1>Compare company experiences</h1><p>Comparisons use only published candidate reports; interview formats vary by role and level.</p><form class="panel selects">@for($i=0;$i<4;$i++)<select name="companies[]"><option value="">Choose company {{$i+1}}</option>@foreach($allCompanies as $option)<option value="{{$option->id}}" @selected((int)request("companies.$i")===$option->id)>{{$option->name}}</option>@endforeach</select>@endfor<button>Compare</button></form>@if($companies->isNotEmpty())<div class="table-wrap"><table><thead><tr><th>Metric</th>@foreach($companies as $company)<th>{{$company->name}}</th>@endforeach</tr></thead><tbody><tr><th>Tier / industry</th>@foreach($companies as $company)<td>{{str_replace('_',' ',strtoupper($company->tier))}}<br>{{$company->industry}}</td>@endforeach</tr><tr><th>Published reports</th>@foreach($companies as $company)<td>{{$company->experiences->count()}}</td>@endforeach</tr><tr><th>Reported difficulties</th>@foreach($companies as $company)<td>{{$company->experiences->pluck('difficulty')->filter()->map(fn($v)=>ucwords(str_replace('_',' ',$v)))->countBy()->map(fn($n,$v)=>"$v: $n")->implode(', ')?:'No reports'}}</td>@endforeach</tr><tr><th>Reported round types</th>@foreach($companies as $company)<td><div class="chips">@foreach($company->experiences->flatMap->rounds->pluck('round_type')->countBy()->sortDesc()->take(8) as $type=>$count)<span>{{ucwords(str_replace('_',' ',$type))}} ({{$count}})</span>@endforeach</div></td>@endforeach</tr><tr><th>Verified compensation reports</th>@foreach($companies as $company)<td>{{$company->packages->count()}}</td>@endforeach</tr></tbody></table></div>@endif</main></body></html>
